CREATE OR REPLACE FUNCTION public.explore_update_page(p_make text DEFAULT ''::text, p_model text DEFAULT ''::text, p_make_id integer DEFAULT 0, p_model_id integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 25, p_by_car_up_to integer DEFAULT 5000)
 RETURNS SETOF public.activity_posts
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  lim integer := least(greatest(coalesce(p_limit, 25), 1), 101);
  skip integer := least(greatest(coalesce(p_offset, 0), 0), 10000);
  car_rule text := 'c.is_public';
  keyset text := '';
